'use strict';
const TRACK_DEFAULTS={basis:'disclosed',period:'365',horizon:'20',min:0,gain:'',win:'',office:'',sort:'avg'};
let trackSettings={...TRACK_DEFAULTS};
function medianTrack(a){if(!a.length)return null;const s=[...a].sort((a,b)=>a-b),m=Math.floor(s.length/2);return s.length%2?s[m]:(s[m-1]+s[m])/2}
function trackRecord(person,settings=trackSettings,records=data,prices=PRICES,now=Date.now()){
 const groups=new Map(),cutoff=settings.period==='all'?-Infinity:now-Number(settings.period)*86400000;
 for(const r of records){if(r.person!==person||r.type!=='Purchase'||!['Stock','ADR','ETF'].includes(r.asset)||r.quality==='User-provided'||Date.parse(r.traded)<cutoff||Date.parse(r.traded)>now)continue;const key=r.ticker+'|'+r.traded,old=groups.get(key);if(!old||(disclosedDate(r)||'9999')<(disclosedDate(old)||'9999'))groups.set(key,r)}
 const returns=[],dates=[],lags=[],drawdowns=[],excess=[];let stale=0,pending=0;
 for(const r of groups.values()){
  const p=prices[r.ticker],d=settings.basis==='trade'?r.traded:disclosedDate(r),gap=disclosureDelay(r);if(gap!==null&&gap>=0)lags.push(gap);if(!d||!p||p.error||!(p.latest>0)||p.asOf<d)continue;
  let entry=d,end=p.asOf,path=[];
  if(settings.horizon){const available=Object.keys(p.closes||{}).filter(k=>k<=p.asOf&&p.closes[k]>0).sort(),start=available.findIndex(k=>settings.basis==='trade'?k===d:k>d),n=Number(settings.horizon);if(start<0||start+n>=available.length){pending++;continue}path=available.slice(start,start+n+1);entry=path[0];end=path.at(-1)}
  const base=p.closes[entry],last=settings.horizon?p.closes[end]:p.latest;if(!(base>0)||!(last>0))continue;const ret=(last/base-1)*100;returns.push(ret);dates.push(end);if(p.stale)stale++;
  if(path.length){let peak=base,worst=0;for(const k of path){const v=p.closes[k];peak=Math.max(peak,v);worst=Math.min(worst,(v/peak-1)*100)}drawdowns.push(worst)}
  const b0=prices.SPY?.closes?.[entry],b1=prices.SPY?.closes?.[end];if(b0>0&&b1>0)excess.push(ret-(b1/b0-1)*100);
 }
 return {count:returns.length,total:groups.size,avg:returns.length?returns.reduce((a,b)=>a+b,0)/returns.length:null,median:medianTrack(returns),win:returns.length?100*returns.filter(n=>n>0).length/returns.length:null,lag:medianTrack(lags),lagCount:lags.length,drawdown:drawdowns.length?Math.min(...drawdowns):null,excess:excess.length?excess.reduce((a,b)=>a+b,0)/excess.length:null,benchmarkCount:excess.length,pending,first:dates.sort()[0],last:dates.at(-1),stale};
}
function rankPeople(people,settings=trackSettings){return people.map(person=>({person,m:trackRecord(person,settings)})).filter(({person,m})=>(!settings.office||ROSTER[person]?.chamber===settings.office)&&m.count>=settings.min&&(settings.gain===''||m.avg!==null&&m.avg>=Number(settings.gain))&&(settings.win===''||m.win!==null&&m.win>=Number(settings.win))).sort((a,b)=>settings.sort==='name'?a.person.localeCompare(b.person):((settings.sort==='count'?b.m.count:settings.sort==='win'?b.m.win:b.m.avg)??-Infinity)-((settings.sort==='count'?a.m.count:settings.sort==='win'?a.m.win:a.m.avg)??-Infinity)||a.person.localeCompare(b.person)).map(x=>x.person)}
function trackCard(person){const m=trackRecord(person),fmt=n=>n===null?'—':(n>=0?'+':'')+n.toFixed(1)+'%',cell=(label,value)=>`<span><small>${label}</small><b>${value}</b></span>`;return `<div class="track-metrics">${cell('Avg. '+trackSettings.horizon+'d '+(trackSettings.basis==='trade'?'after purchase':'after disclosure'),fmt(m.avg))}${cell('Median return',fmt(m.median))}${cell('Win rate',m.win===null?'—':m.win.toFixed(0)+'%')}${cell('Completed / eligible buys',m.count+' / '+m.total)}${cell('Median reporting delay',m.lag===null?'—':m.lag.toFixed(0)+' days')}${cell('Worst drawdown',fmt(m.drawdown))}${cell('Avg. vs SPY',m.excess===null?'—':(m.excess>=0?'+':'')+m.excess.toFixed(1)+' pp')}</div><p class="muted">${m.count<5?'Limited evidence · fewer than 5 completed observations. ':''}${m.benchmarkCount}/${m.count} benchmark matches · ${m.lagCount} dated purchases${m.pending?' · '+m.pending+' awaiting a full window':''}<br>Window ends ${m.first?date(m.first)+(m.last!==m.first?'–'+date(m.last):''):'unavailable'}${m.stale?' · '+m.stale+' stale':''}</p>`}
function initTrackFilters(){const ids={Basis:'basis',Period:'period',Horizon:'horizon',Min:'min',Gain:'gain',Win:'win',Office:'office',Sort:'sort'};for(const [suffix,key]of Object.entries(ids)){$('#track'+suffix).value=String(trackSettings[key]);$('#track'+suffix).addEventListener(['Gain','Win'].includes(suffix)?'input':'change',()=>{trackSettings[key]=$('#track'+suffix).value;renderPeople()})}$('#trackReset').onclick=()=>{trackSettings={...TRACK_DEFAULTS};for(const [suffix,key]of Object.entries(ids))$('#track'+suffix).value=String(trackSettings[key]);renderPeople()}}
